<?php if (!$mcLoggedIn): ?><dialog id="mc-login-dialog" class="mc-login-dialog" aria-labelledby="mc-login-title"><form id="mc-login-form" method="post" action="<?php $this->options->loginAction(); ?>"><div class="mc-login-heading"><h2 id="mc-login-title">⚒ 玩家登录</h2><button type="button" class="mc-login-close" id="mc-login-close" aria-label="关闭登录框">×</button></div><label for="mc-name">用户名</label><input id="mc-name" name="name" autocomplete="username" required><label for="mc-password">密码</label><div class="mc-password-wrap"><input id="mc-password" type="password" name="password" autocomplete="current-password" aria-describedby="mc-login-error" required><button type="button" id="mc-toggle-password" class="mc-toggle-password" aria-label="显示密码" aria-pressed="false"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="mc-eye-slash" d="M3 3l18 18" style="display:none"/></svg></button></div><p id="mc-login-error" class="mc-login-error" role="alert" aria-live="polite" hidden></p><label class="mc-remember"><input type="checkbox" name="remember" value="1"> 记住登录状态</label><input type="hidden" name="referer" value="<?php echo htmlspecialchars($this->request->getRequestUrl(), ENT_QUOTES, 'UTF-8'); ?>"><button type="submit">进入世界</button></form></dialog><script>(function(){const d=document.getElementById('mc-login-dialog');document.getElementById('mc-login-open').addEventListener('click',()=>d.showModal());document.getElementById('mc-login-close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d)d.close()});const form=document.getElementById('mc-login-form'),pwd=document.getElementById('mc-password'),toggle=document.getElementById('mc-toggle-password'),error=document.getElementById('mc-login-error'),submit=form.querySelector('button[type=submit]');toggle.addEventListener('click',()=>{const visible=pwd.type==='password';pwd.type=visible?'text':'password';toggle.querySelector('.mc-eye-slash').style.display=visible?'':'none';toggle.setAttribute('aria-label',visible?'隐藏密码':'显示密码');toggle.setAttribute('aria-pressed',String(visible))});form.addEventListener('submit',async e=>{e.preventDefault();error.hidden=true;pwd.removeAttribute('aria-invalid');submit.disabled=true;submit.textContent='验证中…';try{const res=await fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin',redirect:'follow'});if(!res.ok)throw new Error('HTTP '+res.status);const html=await res.text();const doc=new DOMParser().parseFromString(html,'text/html');if(doc.querySelector('.account-name')){window.location.reload();return}error.textContent='用户名或密码不正确，请重新输入。';error.hidden=false;pwd.setAttribute('aria-invalid','true');pwd.focus();pwd.select()}catch(err){error.textContent='登录请求失败，请稍后重试。';error.hidden=false}finally{submit.disabled=false;submit.textContent='进入世界'}})})();</script><?php endif; ?>
